-- ============================================================
-- Kalender pendidikan (kaldik) — dipindah masuk ke sistem ini
-- ============================================================
-- 📋 CARA PAKAI: Supabase SQL Editor → paste seluruh file → Run.
--    Idempoten (boleh dijalankan ulang; baris yang sudah ada dilewati).
--
-- Yang berubah:
--   • kaldik_events → BARU, beserta isinya (460 agenda tahun 2026)
--
-- ── KENAPA DIPINDAH ─────────────────────────────────────────
--
-- Agenda kaldik sebelumnya hidup di aplikasi terpisah (kaldikrqlhi) dengan
-- proyek Supabase sendiri, dan dibaca lewat HTTP. Akibatnya: dua akun untuk
-- dua aplikasi, kalender beranda ikut mati kalau aplikasi itu mati, dan
-- Kalender Qur'an baru melihat agenda baru setelah singgahan 5 menit lewat.
-- Setelah pindah, agenda menjadi tabel biasa di basis data yang sama —
-- dibaca langsung, disunting dengan akun yang sama, dan tunduk pada RBAC
-- yang sama.
--
-- ── DUPLIKAT DIBERSIHKAN SEKALIAN ───────────────────────────
--
-- Sumbernya berisi 722 baris untuk 2026, tapi hanya 460 yang benar-benar
-- berbeda: agenda yang sama ter-seed dua kali. Selama ini duplikat itu
-- dibuang ulang di setiap permintaan halaman (lihat komentar lama di
-- app/page.tsx). Yang dipindahkan hanyalah yang unik menurut
-- (tanggal, judul, unit), dan indeks unik di bawah menjaganya tetap begitu.
--
-- ── SETELAH INI ─────────────────────────────────────────────
--
-- Aplikasi kaldikrqlhi boleh dipensiunkan. Sampai tabel ini ada, kode tetap
-- jatuh ke API lama, jadi urutan menjalankannya tidak kritis.
-- ============================================================

CREATE TABLE IF NOT EXISTS "kaldik_events" (
  "id"          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  "date"        date NOT NULL,
  "title"       text NOT NULL,
  "description" text,
  /* NASIONAL | SD | SMP | RQ — dibiarkan text, bukan enum: daftar unit di
     kaldik tidak sama dengan enum jenjang sistem ini (tidak ada PAUD/SMA,
     ada NASIONAL & RQ), dan memaksanya masuk enum jenjang akan menghapus
     perbedaan yang justru bermakna di kalender. */
  "unit"        text NOT NULL DEFAULT 'NASIONAL',
  /* libur_nasional | libur_semester | ramadhan | agenda | kegiatan_bersama */
  "type"        text NOT NULL DEFAULT 'agenda',
  "color"       text NOT NULL DEFAULT '#3B82F6',
  /* Redundan terhadap date, tapi dipertahankan: penyaringan per tahun adalah
     kueri paling sering di kalender, dan kolomnya sudah ada di data asal. */
  "year"        integer NOT NULL,
  "created_by"  uuid REFERENCES "users"("id") ON DELETE SET NULL,
  "created_at"  timestamptz NOT NULL DEFAULT now(),
  "updated_at"  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS "kaldik_events_year_idx" ON "kaldik_events" ("year");
CREATE INDEX IF NOT EXISTS "kaldik_events_date_idx" ON "kaldik_events" ("date");

-- Satu agenda hanya sekali per (tanggal, judul, unit) — inilah yang membuat
-- duplikat tidak bisa kembali lewat impor ulang.
CREATE UNIQUE INDEX IF NOT EXISTS "kaldik_events_unik"
  ON "kaldik_events" ("date", "title", "unit");

ALTER TABLE "kaldik_events" ENABLE ROW LEVEL SECURITY;

-- ── Isi: agenda 2026 dari kaldikrqlhi ───────────────────────

ON CONFLICT DO NOTHING;
